WITH filtered AS (SELECT id, session_id, page, event_time, duration_sec, ROUND(duration_sec, 0) AS duration_sec_rounded, COALESCE(page, 'NONE') AS page_filled FROM web_events WHERE event_time > TIMESTAMP '2023-07-15 14:00:00' AND page IS NOT NULL) SELECT p.country, p.device, s.page, COUNT(*) AS cnt, MAX(s.duration_sec) AS max_duration_sec FROM filtered s LEFT JOIN sessions p ON s.session_id = p.id GROUP BY CUBE (p.country, p.device, s.page);
